-- Esquema reconstruido a partir de models/ y datos de ejemplo ficticios para la demo local.
-- No es el esquema original. Usuario de prueba: admin@demo.test / demo1234
CREATE DATABASE IF NOT EXISTS devwebcamp_demo CHARACTER SET utf8mb4; USE devwebcamp_demo;
CREATE TABLE categorias(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60));
CREATE TABLE dias(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30));
CREATE TABLE horas(id INT AUTO_INCREMENT PRIMARY KEY,hora VARCHAR(20));
CREATE TABLE paquetes(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(30));
CREATE TABLE regalos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60));
CREATE TABLE ponentes(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(40),apellido VARCHAR(40),ciudad VARCHAR(40),pais VARCHAR(40),imagen VARCHAR(40),tags VARCHAR(120),redes TEXT);
CREATE TABLE eventos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120),descripcion TEXT,disponibles INT,categoria_id INT,dia_id INT,hora_id INT,ponente_id INT);
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(40),apellido VARCHAR(40),email VARCHAR(60),password VARCHAR(60),confirmado TINYINT(1),token VARCHAR(15),admin TINYINT(1));
CREATE TABLE registros(id INT AUTO_INCREMENT PRIMARY KEY,paquete_id INT,pago_id VARCHAR(30),token VARCHAR(8),usuario_id INT,regalo_id INT);
CREATE TABLE eventos_registros(id INT AUTO_INCREMENT PRIMARY KEY,evento_id INT,registro_id INT);
